// Test/phase runner. JSON stdin/stdout is an external fixture interface, never wire framing.
use std::{io::{self,BufRead},time::Instant};
use v13_codec_experiment::*;
fn main(){for line in io::stdin().lock().lines(){let line=line.unwrap();let result=std::panic::catch_unwind(||run(&line));match result{Ok(Ok(v))=>println!("{v}"),Ok(Err(e))=>println!("{}",serde_json::json!({"error":e})),Err(_)=>println!("{{\"error\":\"panic\"}}")}}}
fn run(s:&str)->Result<serde_json::Value,String>{let j:serde_json::Value=serde_json::from_str(s).map_err(|e|e.to_string())?;let codec=j["codec"].as_str().ok_or("codec")?;
 if codec=="json"{let a=Instant::now();let b=serde_json::to_vec(&j["value"]).map_err(|e|e.to_string())?;return Ok(serde_json::json!({"bytes":b,"prepare_ns":0,"encode_ns":a.elapsed().as_nanos() as u64}));}let bytes=if j["op"]=="decode"{j["bytes"].as_array().ok_or("bytes")?.iter().map(|x|x.as_u64().filter(|n|*n<256).map(|n|n as u8).ok_or("byte".to_owned())).collect::<Result<Vec<_>,_>>()?}else{let a=Instant::now();let v=if j["op"]=="encode_binary"{Value{value:Some(value::V::Binary(j["bytes"].as_array().ok_or("bytes")?.iter().map(|x|x.as_u64().filter(|n|*n<256).map(|n|n as u8).ok_or("byte".to_owned())).collect::<Result<_,_>>()?))}}else{prepare(&j["value"])?};let prep=a.elapsed().as_nanos() as u64;let a=Instant::now();let b=match codec{"protobuf"=>encode_pb(&v)?,"msgpack"=>encode_mp(&v)?,_=>return Err("codec".into())};let ns=a.elapsed().as_nanos() as u64;return Ok(serde_json::json!({"bytes":b,"prepare_ns":prep,"encode_ns":ns}));};
 let v=match codec{"protobuf"=>decode_pb(&bytes)?,"msgpack"=>decode_mp(&bytes)?,_=>return Err("codec".into())};if let Some(value::V::Binary(b))=v.value{Ok(serde_json::json!({"binary":b}))}else{Ok(serde_json::json!({"value":adapt(&v)?}))}}
